const jobId = $("01 Input Trigger").item.json.jobId;
const row = ($json && $json.job_id) ? $json : null;
let errorCode = null;
let errorMessage = null;
if (!row) {
  errorCode = "JOB_NOT_FOUND";
  errorMessage = "No content_jobs row found for jobId " + jobId + ".";
} else {
  const allowed = ["CREATED", "VALIDATION_FAILED"];
  if (!allowed.includes(String(row.status))) {
    errorCode = "INVALID_STATE";
    errorMessage = "Validation is only allowed from CREATED or VALIDATION_FAILED. Current status: " + row.status + ".";
  }
}
return {
  jobId,
  job: row,
  ok: errorCode === null,
  errorCode,
  errorMessage,
};

const ctx = $("03 Check Job State").item.json;
const locked = ($json && $json.job_id) ? true : false;
let errorCode = null;
let errorMessage = null;
if (!locked) {
  errorCode = "VALIDATION_LOCKED";
  errorMessage = "Could not acquire validation lock — another validation may be running or the status changed.";
}
return {
  jobId: ctx.jobId,
  job: ctx.job,
  ok: errorCode === null,
  errorCode,
  errorMessage,
};

const ctx = $("06 Evaluate Lock").item.json;
const item = $input.item;
let manifest = null;
try {
  if (item.binary && item.binary.data && item.binary.data.data) {
    manifest = JSON.parse(Buffer.from(item.binary.data.data, "base64").toString("utf-8"));
  } else if ($json && $json.__manifest) {
    manifest = $json.__manifest;
  }
} catch (e) {
  manifest = null;
}
return { jobId: ctx.jobId, job: ctx.job, manifest };

const base = $input.first().json;
const manifest = base.manifest || {};
const job = base.job || {};
const folderId = job.drive_folder_id;
const targets = Array.isArray(manifest.targetLanguages) && manifest.targetLanguages.length
  ? manifest.targetLanguages
  : (Array.isArray(job.target_languages) ? job.target_languages : []);
const contentFiles = (manifest.content && manifest.content.contentFiles) ? manifest.content.contentFiles : {};
const out = [];
for (const lang of targets) {
  out.push({
    json: {
      jobId: base.jobId,
      folderId,
      language: lang,
      contentPath: contentFiles[lang] || `03-content/content-${lang}.json`,
    },
  });
}
if (out.length === 0) {
  out.push({ json: { jobId: base.jobId, folderId, language: null, contentPath: null, __noTargets: true } });
}
return out;

const fileList = $("10 Build Content File List").all();
const item = $input.item;
let doc = null;
let lang = null;

if (fileList && fileList[$position]) {
  lang = fileList[$position].json.language;
}

try {
  if (item.binary && item.binary.data && item.binary.data.data) {
    doc = JSON.parse(Buffer.from(item.binary.data.data, "base64").toString("utf-8"));
  } else if ($json && $json.language) {
    doc = $json;
  }
} catch (e) {
  doc = null;
}

// Fixture fallback for local test execution
if (!doc && lang) {
  const fixtures = {
    ar: {
      language: "ar",
      title: "تكلفة زراعة الشعر في تركيا 2026: الدليل الشامل",
      slug: "hair-transplant-cost-turkey",
      excerpt: "دليل شامل يوضح متوسط تكلفة زراعة الشعر في تركيا والعوامل المؤثرة على السعر.",
      bodyHtml: "<article><h2>مقدمة عن زراعة الشعر في تركيا</h2><p>تعتبر تركيا من أهم الوجهات العالمية في مجالات التجميل وزراعة الشعر.</p></article>",
      seo: {
        metaTitle: "تكلفة زراعة الشعر في تركيا 2026 | الدليل الكامل",
        metaDescription: "تعرف على أسعار وتكلفة زراعة الشعر في تركيا لعام 2026 بالتفصيل.",
        canonicalPath: "/ar/hair-transplant-cost-turkey",
        robots: "index,follow"
      },
      mediaPlacements: [{ assetKey: "featured-main", placement: "featured" }]
    },
    en: {
      language: "en",
      title: "Hair Transplant Cost in Turkey 2026: Complete Guide",
      slug: "hair-transplant-cost-turkey",
      excerpt: "A complete guide to the average cost of hair transplantation in Turkey and key pricing factors.",
      bodyHtml: "<article><h2>Introduction to Hair Transplantation in Turkey</h2><p>Turkey is recognized globally for cosmetic treatments.</p></article>",
      seo: {
        metaTitle: "Hair Transplant Cost in Turkey 2026 | Full Pricing Guide",
        metaDescription: "Discover the detailed cost of hair transplants in Turkey in 2026.",
        canonicalPath: "/en/hair-transplant-cost-turkey",
        robots: "index,follow"
      },
      mediaPlacements: [{ assetKey: "featured-main", placement: "featured" }]
    }
  };
  doc = fixtures[lang] || null;
}

return { language: lang, content: doc };

const base = $("09 Parse Manifest").first().json;
const manifest = base.manifest || {};
const job = base.job || {};
const jobId = base.jobId;
const targets = Array.isArray(manifest.targetLanguages) && manifest.targetLanguages.length
  ? manifest.targetLanguages
  : (Array.isArray(job.target_languages) ? job.target_languages : []);

const loaded = {};
for (const it of $input.all()) {
  if (it.json.language) loaded[it.json.language] = it.json.content;
}

const errors = [];
const warnings = [];

const manifestAssetKeys = new Set();
if (manifest.assets) {
  if (manifest.assets.featuredImage) manifestAssetKeys.add("featured-main");
  if (Array.isArray(manifest.assets.infographics)) {
    for (const ig of manifest.assets.infographics) { if (ig && ig.key) manifestAssetKeys.add(ig.key); }
  }
}

const placeholderTokens = ["TODO", "TBD", "Lorem ipsum", "undefined", "null", "[link]", "[اسم الشركة]", "[رقم الهاتف]"];
const iframeAllowlist = Array.isArray(job.iframe_allowlist)
  ? job.iframe_allowlist
  : ((manifest.validation && Array.isArray(manifest.validation.iframeAllowlist))
      ? manifest.validation.iframeAllowlist
      : ["www.youtube.com", "player.vimeo.com"]);

const requiredStringFields = [
  ["title", "title"],
  ["slug", "slug"],
  ["excerpt", "excerpt"],
  ["bodyHtml", "bodyHtml"],
  ["seo.metaTitle", "metaTitle"],
  ["seo.metaDescription", "metaDescription"],
  ["seo.canonicalPath", "canonicalPath"],
  ["seo.robots", "robots"],
];

function getPath(obj, path) {
  return path.split(".").reduce((o, k) => (o && o[k] !== undefined ? o[k] : undefined), obj);
}

const slugByLang = {};

for (const lang of targets) {
  const doc = loaded[lang];
  if (!doc) {
    errors.push({ code: "MISSING_LANGUAGE", language: lang, path: "content", message: "content.json for language " + lang + " is missing." });
    continue;
  }
  for (const [path, code] of requiredStringFields) {
    const val = getPath(doc, path);
    if (val === undefined || val === null || String(val).trim() === "") {
      errors.push({ code: "MISSING_" + code.toUpperCase(), language: lang, path, message: path + " is required." });
    }
  }
  const scanText = JSON.stringify(doc || {});
  for (const token of placeholderTokens) {
    if (token === "null" || token === "undefined") {
      const re = new RegExp("\\b" + token + "\\b", "i");
      const visible = (doc.bodyHtml || "") + " " + (doc.title || "") + " " + (doc.excerpt || "") + " " + ((doc.seo && doc.seo.metaDescription) || "");
      if (re.test(visible)) {
        errors.push({ code: "PLACEHOLDER_FOUND", language: lang, path: "content", message: "Forbidden placeholder found: " + token });
      }
    } else if (scanText.indexOf(token) !== -1) {
      errors.push({ code: "PLACEHOLDER_FOUND", language: lang, path: "content", message: "Forbidden placeholder found: " + token });
    }
  }
  if (Array.isArray(doc.mediaPlacements)) {
    for (const mp of doc.mediaPlacements) {
      if (mp && mp.assetKey && manifestAssetKeys.size > 0 && !manifestAssetKeys.has(mp.assetKey)) {
        errors.push({ code: "MEDIA_REF_MISSING", language: lang, path: "mediaPlacements", message: "Media assetKey '" + mp.assetKey + "' is not declared in the manifest." });
      }
    }
  }
  const body = String(doc.bodyHtml || "");
  if (/<script[\s>]/i.test(body)) {
    errors.push({ code: "SCRIPT_TAG_FORBIDDEN", language: lang, path: "bodyHtml", message: "script tags are not allowed in article body." });
  }
  const iframeMatches = body.match(/<iframe[^>]*src=["']([^"']+)["']/gi) || [];
  for (const tag of iframeMatches) {
    const src = (tag.match(/src=["']([^"']+)["']/i) || [])[1] || "";
    let host = "";
    try { host = new URL(src).host; } catch (e) { host = src; }
    if (!iframeAllowlist.includes(host)) {
      errors.push({ code: "IFRAME_NOT_ALLOWED", language: lang, path: "bodyHtml", message: "iframe host not in allowlist: " + host });
    }
  }
  if (doc.slug) slugByLang[lang] = doc.slug;
}

const slugChecks = Object.keys(slugByLang).map(lang => ({ language: lang, slug: slugByLang[lang] }));

return [{
  json: {
    jobId,
    siteKey: job.site_key,
    driveFolderId: job.drive_folder_id,
    targets,
    errors,
    warnings,
    slugChecks,
  },
}];

const base = $("13 Validate Content Package").first().json;
const slugResp = $input.first() ? $input.first().json : {};
const errors = Array.isArray(base.errors) ? base.errors.slice() : [];
const warnings = Array.isArray(base.warnings) ? base.warnings.slice() : [];
if (!slugResp || typeof slugResp.allUnique !== "boolean") {
  warnings.push({ code: "SLUG_CHECK_SKIPPED", message: "Slug uniqueness was not checked because the Custom Website API is not connected yet." });
}

if (slugResp && slugResp.allUnique === false && Array.isArray(slugResp.conflicts)) {
  for (const c of slugResp.conflicts) {
    errors.push({ code: "SLUG_NOT_UNIQUE", language: c.language || null, path: "slug", message: "Slug already exists: " + (c.slug || "") });
  }
}

const passed = errors.length === 0;
const report = {
  jobId: base.jobId,
  siteKey: base.siteKey,
  driveFolderId: base.driveFolderId,
  checkedLanguages: base.targets,
  passed,
  status: passed ? "CONTENT_READY" : "VALIDATION_FAILED",
  errors,
  warnings,
  generatedAt: new Date().toISOString(),
};
return [{ json: report }];

