SET status = $2, last_error = $3, updated_at = NOW()
WHERE job_id = $1;

parameters.jsCode:
const r = $("15 Compile Validation Result").item.json;
if (r.passed) {
  return {
    success: true,
    jobId: r.jobId,
    status: "CONTENT_READY",
    message: "Content package validated successfully.",
    data: { checkedLanguages: r.checkedLanguages },
    warnings: r.warnings,
    errors: [],
    nextAllowedActions: ["prepare_assets", "cancel"],
  };
}
return {
  success: false,
  jobId: r.jobId,
  status: "VALIDATION_FAILED",
  message: "Content package contains validation errors.",
  data: null,
  warnings: r.warnings,
  errors: r.errors,
  nextAllowedActions: ["retry", "cancel"],
};

const j = $json || {};
const code = j.errorCode || "UNKNOWN_ERROR";
const message = j.errorMessage || "An unknown error occurred while validating the content package.";
let jobId = j.jobId || null;
if (!jobId) { try { jobId = $("01 Input Trigger").item.json.jobId || null; } catch (e) { jobId = null; } }
const retryable = ["VALIDATION_LOCKED", "INVALID_STATE"];
const nextAllowedActions = retryable.includes(code) ? ["retry", "cancel"] : ["cancel"];
return {
  success: false,
  jobId,
  status: "FAILED",
  message,
  data: null,
  warnings: [],
  errors: [{ code, language: null, path: null, message }],
  nextAllowedActions,
};
